package com.asmj.marketplace.advertising;
import com.asmj.marketplace.audit.AuditService; import com.asmj.marketplace.model.*; import com.asmj.marketplace.product.*; import com.asmj.marketplace.repository.*; import com.asmj.marketplace.service.CloudinaryImageService; import com.asmj.marketplace.notification.NotificationService;
import jakarta.servlet.http.HttpSession; import java.math.BigDecimal; import java.security.Principal; import java.time.*; import java.util.*;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class AdvertisingController {
 private final AdCampaignRepository campaigns; private final AdPlacementRepository placements; private final AdPackageRepository packages; private final AdvertisingSettingsRepository settings; private final AdEventRepository events; private final AdvertisingService service; private final UserAccountRepository users; private final ProductRepository products; private final CategoryRepository categories; private final CloudinaryImageService uploads; private final AuditService audit; private final NotificationService notifications;
 public AdvertisingController(AdCampaignRepository c,AdPlacementRepository p,AdPackageRepository a,AdvertisingSettingsRepository s,AdEventRepository e,AdvertisingService v,UserAccountRepository u,ProductRepository pr,CategoryRepository cat,CloudinaryImageService up,AuditService au,NotificationService ns){campaigns=c;placements=p;packages=a;settings=s;events=e;service=v;users=u;products=pr;categories=cat;uploads=up;audit=au;notifications=ns;}
 @GetMapping("/vendor/advertising") public String vendorHome(Principal principal,Model m){service.ensureDefaults();UserAccount u=user(principal);m.addAttribute("campaigns",campaigns.findByVendorUserIdOrderByCreatedAtDesc(u.getId()).stream().filter(c->!c.isVendorDeleted()).toList());m.addAttribute("products",products.findByVendorUserIdOrderByCreatedAtDesc(u.getId()).stream().filter(p->p.getStatus()==ProductStatus.ACTIVE).toList());m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());List<AdCampaign> vendorCampaigns=campaigns.findByVendorUserIdOrderByCreatedAtDesc(u.getId());m.addAttribute("totalImpressions",vendorCampaigns.stream().mapToLong(AdCampaign::getImpressions).sum());m.addAttribute("totalClicks",vendorCampaigns.stream().mapToLong(AdCampaign::getClicks).sum());m.addAttribute("placements",placements.findByEnabledTrueOrderByNameAsc());m.addAttribute("packages",packages.findByEnabledTrueOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("adSettings",service.currentSettings());return "vendor/advertising";}
 @GetMapping("/vendor/advertising/new") public String createForm(Principal principal,Model m){service.ensureDefaults();m.addAttribute("placements",placements.findByEnabledTrueOrderByNameAsc());m.addAttribute("packages",packages.findByEnabledTrueOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("products",products.findByVendorUserIdOrderByCreatedAtDesc(user(principal).getId()).stream().filter(p->p.getStatus()==ProductStatus.ACTIVE).toList());m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());m.addAttribute("minimumStartDate",LocalDate.now(ZoneId.of("Asia/Kolkata")));m.addAttribute("adSettings",service.currentSettings());return "advertising/create";}
 @PostMapping("/vendor/advertising/create") public String create(Principal principal,@RequestParam String placementCode,@RequestParam String packageId,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) List<String> productIds,@RequestParam(required=false) List<String> categoryIds,@RequestParam(defaultValue="SINGLE_PRODUCT") String campaignType,@RequestParam(required=false) String destinationUrl,@RequestParam String startDate,@RequestParam(required=false) String targetPinCodes,@RequestParam(defaultValue="CUSTOM") String bannerMode,@RequestParam(required=false) MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,RedirectAttributes ra){
  try{UserAccount u=user(principal);if(!service.currentSettings().isEnabled()||service.currentSettings().getUpiId()==null||service.currentSettings().getUpiId().isBlank())throw new IllegalArgumentException("Advertising is temporarily unavailable. Please contact ASMJ Shoppe admin.");AdPlacement p=placements.findByCode(placementCode).filter(AdPlacement::isEnabled).orElseThrow(()->new IllegalArgumentException("Choose an available advertising placement."));AdPackage pkg=packages.findByIdAndEnabledTrue(packageId).filter(x->placementCode.equals(x.getPlacementCode())).orElseThrow(()->new IllegalArgumentException("Choose a valid package for the selected placement."));if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");LocalDate start=LocalDate.parse(startDate);LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(start.isBefore(today)||start.isAfter(today.plusDays(90)))throw new IllegalArgumentException("Choose a campaign start date from today through the next 90 days.");String target=destinationUrl==null?"":destinationUrl.trim();String selectedProductId=(productId==null||productId.isBlank())?null:productId;List<String> selectedProducts=new ArrayList<>();List<String> selectedCategories=new ArrayList<>();if("MULTI_PRODUCT".equals(campaignType)){selectedProducts=validateCampaignProducts(productIds,u.getId());if(selectedProducts.size()<2)throw new IllegalArgumentException("Select at least two active products for a multi-product campaign.");selectedProductId=null;categoryId=null;target="/ads/campaign/"+"NEW";}else if("CATEGORY".equals(campaignType)){selectedCategories=validateCampaignCategories(categoryIds);if(selectedCategories.isEmpty())throw new IllegalArgumentException("Select at least one active category.");selectedProductId=null;categoryId=selectedCategories.get(0);target="/ads/campaign/"+"NEW";}else if(!"SINGLE_PRODUCT".equals(campaignType))throw new IllegalArgumentException("Choose a valid campaign type.");if(selectedProductId!=null){Product product=products.findById(selectedProductId).filter(x->u.getId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select one of your active products."));String productTarget="/products/"+product.getId();if(target.isBlank()||target.equals(productTarget)){target=productTarget;categoryId=product.getCategoryId();}else{selectedProductId=null;}}if(categoryId!=null&&!categoryId.isBlank()){String selectedCategory=categoryId;categories.findById(selectedCategory).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Choose one of your active products or a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);String bannerUrl; if("PRODUCT_IMAGE".equalsIgnoreCase(bannerMode)){if(!"SINGLE_PRODUCT".equals(campaignType)||selectedProductId==null)throw new IllegalArgumentException("Select a promoted product to use its product image as the advertisement banner, or choose a separate banner.");Product bannerProduct=products.findById(selectedProductId).orElseThrow(()->new IllegalArgumentException("Promoted product not found."));if(bannerProduct.getImageUrl()==null||bannerProduct.getImageUrl().isBlank())throw new IllegalArgumentException("The selected product has no image. Upload a product image or choose a separate advertisement banner.");bannerUrl=bannerProduct.getImageUrl();}else{if(banner==null||banner.isEmpty())throw new IllegalArgumentException("Upload a separate advertisement banner.");bannerUrl=(String)uploads.uploadAdvertisementBanner(banner).get("secure_url");}String mobileUrl=null;if(mobileBanner!=null&&!mobileBanner.isEmpty())mobileUrl=(String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url");AdCampaign c=new AdCampaign();c.setVendorUserId(u.getId());c.setVendorName(u.getFullName());c.setPlacementCode(p.getCode());c.setPlacementName(p.getName());c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());c.setBannerUrl(bannerUrl);c.setBannerUsesProductImage("PRODUCT_IMAGE".equalsIgnoreCase(bannerMode));c.setMobileBannerUrl(mobileUrl);c.setDestinationUrl(target);c.setProductId(selectedProductId);c.setCategoryId(categoryId);c.setCampaignType(campaignType);c.setProductIds(selectedProducts);c.setCategoryIds(selectedCategories);c.setTargetPinCodes(pins);c.setDurationDays(pkg.getDurationDays());c.setStartDate(start);c.setEndDate(start.plusDays(pkg.getDurationDays()-1L));c.setAmount(pkg.getPrice());c.setStatus("PENDING_PAYMENT");c.setPaymentStatus("PENDING");c.setApprovalStatus("PENDING");c.setCreatedAt(Instant.now());c.setUpdatedAt(Instant.now());campaigns.save(c);if("MULTI_PRODUCT".equals(campaignType)||"CATEGORY".equals(campaignType)){c.setDestinationUrl("/ads/campaign/"+c.getId());campaigns.save(c);}notifications.notifyAdmins("New advertisement submitted",u.getFullName()+" submitted the campaign "+c.getTitle()+" for review and payment.","AD_CAMPAIGN",c.getId());audit.record(u.getEmail(),"VENDOR","AD_CAMPAIGN_CREATED","AD_CAMPAIGN",c.getId(),"Campaign submitted for UPI payment and creative review.");ra.addFlashAttribute("successMessage","Campaign created. Complete UPI payment and submit your UTR and screenshot.");return "redirect:/vendor/advertising/"+c.getId()+"/payment";}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));return "redirect:/vendor/advertising/new";}}

 @GetMapping("/vendor/advertising/{id}/edit") public String vendorEditForm(@PathVariable String id,Principal principal,Model m,RedirectAttributes ra){AdCampaign c=owned(id,principal);if(c==null||c.isVendorDeleted()||"REFUNDED".equals(c.getPaymentStatus())||"REFUNDED".equals(c.getRefundStatus())||"EXPIRED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","This advertisement cannot be edited.");return "redirect:/vendor/advertising";}m.addAttribute("campaign",c);m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());m.addAttribute("products",products.findByVendorUserIdOrderByCreatedAtDesc(user(principal).getId()).stream().filter(x->x.getStatus()==ProductStatus.ACTIVE).toList());return "vendor/advertising-edit";}
 @PostMapping("/vendor/advertising/{id}/edit") public String vendorUpdate(@PathVariable String id,Principal principal,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) List<String> productIds,@RequestParam(required=false) List<String> categoryIds,@RequestParam(defaultValue="SINGLE_PRODUCT") String campaignType,@RequestParam(required=false) String destinationUrl,@RequestParam(required=false) String targetPinCodes,@RequestParam(defaultValue="CUSTOM") String bannerMode,@RequestParam(required=false) MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,RedirectAttributes ra){try{AdCampaign c=owned(id,principal);if(c==null||c.isVendorDeleted()||"REFUNDED".equals(c.getPaymentStatus())||"REFUNDED".equals(c.getRefundStatus())||"EXPIRED".equals(c.getStatus()))throw new IllegalArgumentException("This advertisement cannot be edited.");if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");String target=destinationUrl==null?"":destinationUrl.trim();String savedProductId=(productId==null||productId.isBlank())?null:productId;if(savedProductId!=null){Product product=products.findById(savedProductId).filter(x->user(principal).getId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select one of your active products."));String productTarget="/products/"+product.getId();if(target.isBlank()||target.equals(productTarget)){target=productTarget;categoryId=product.getCategoryId();}else{savedProductId=null;}}if(categoryId!=null&&!categoryId.isBlank()){String selected=categoryId;categories.findById(selected).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Use a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);if("PRODUCT_IMAGE".equalsIgnoreCase(bannerMode)){if(!"SINGLE_PRODUCT".equals(campaignType)||savedProductId==null)throw new IllegalArgumentException("Select a promoted product to use its image as the advertisement banner, or choose a separate banner.");Product bannerProduct=products.findById(savedProductId).orElseThrow(()->new IllegalArgumentException("Promoted product not found."));if(bannerProduct.getImageUrl()==null||bannerProduct.getImageUrl().isBlank())throw new IllegalArgumentException("The selected product has no image. Choose a separate advertisement banner.");c.setBannerUrl(bannerProduct.getImageUrl());c.setBannerUsesProductImage(true);}else{if(banner!=null&&!banner.isEmpty()){c.setBannerUrl((String)uploads.uploadAdvertisementBanner(banner).get("secure_url"));}else if(c.isBannerUsesProductImage()){throw new IllegalArgumentException("Upload a separate advertisement banner or choose a product image.");}c.setBannerUsesProductImage(false);}if(mobileBanner!=null&&!mobileBanner.isEmpty())c.setMobileBannerUrl((String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url"));c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());if("MULTI_PRODUCT".equals(campaignType)){List<String> valid=validateCampaignProducts(productIds,c.getVendorUserId());if(valid.size()<2)throw new IllegalArgumentException("Select at least two active products for a multi-product campaign.");savedProductId=null;categoryId=null;target="/ads/campaign/"+c.getId();c.setProductIds(valid);c.setCategoryIds(new ArrayList<>());}else if("CATEGORY".equals(campaignType)){List<String> valid=validateCampaignCategories(categoryIds);if(valid.isEmpty())throw new IllegalArgumentException("Select at least one active category.");savedProductId=null;categoryId=valid.get(0);target="/ads/campaign/"+c.getId();c.setProductIds(new ArrayList<>());c.setCategoryIds(valid);}else{c.setProductIds(new ArrayList<>());c.setCategoryIds(new ArrayList<>());}c.setCampaignType(campaignType);c.setProductId(savedProductId);c.setCategoryId(categoryId==null||categoryId.isBlank()?null:categoryId);c.setDestinationUrl(target);c.setTargetPinCodes(pins);c.setApprovalStatus("PENDING");c.setApprovedBy(null);c.setApprovedAt(null);c.setRejectionReason(null);if("VERIFIED".equals(c.getPaymentStatus()))c.setStatus("PAYMENT_VERIFIED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyAdmins("Advertisement updated by vendor",c.getVendorName()+" updated the campaign "+c.getTitle()+". Creative approval is pending review.","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"VENDOR","AD_CAMPAIGN_EDITED","AD_CAMPAIGN",id,"Vendor updated creative and targeting; approval reset for review.");ra.addFlashAttribute("successMessage","Advertisement updated. It has been sent for admin review; existing payment and campaign dates are preserved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/vendor/advertising";}
 @PostMapping("/vendor/advertising/{id}/delete") public String vendorDelete(@PathVariable String id,Principal principal,RedirectAttributes ra){AdCampaign c=owned(id,principal);if(c==null||c.isVendorDeleted()){ra.addFlashAttribute("errorMessage","Advertisement not found.");return "redirect:/vendor/advertising";}if("REFUNDED".equals(c.getPaymentStatus())||"REFUNDED".equals(c.getRefundStatus())){ra.addFlashAttribute("errorMessage","This refunded campaign is retained for financial records and cannot be deleted.");return "redirect:/vendor/advertising";}c.setVendorDeleted(true);c.setVendorDeletedAt(Instant.now());c.setStatus("SUSPENDED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"VENDOR","AD_CAMPAIGN_VENDOR_DELETED","AD_CAMPAIGN",id,"Vendor removed advertisement from their campaign list; record retained for audit and payment history.");ra.addFlashAttribute("successMessage","Advertisement removed from your list. Financial and audit records are retained.");return "redirect:/vendor/advertising";}
 @GetMapping("/vendor/advertising/{id}/payment") public String payment(@PathVariable String id,Principal principal,Model m,RedirectAttributes ra){AdCampaign c=owned(id,principal);if(c==null){ra.addFlashAttribute("errorMessage","Campaign not found.");return "redirect:/vendor/advertising";}m.addAttribute("campaign",c);m.addAttribute("adSettings",service.currentSettings());return "advertising/payment";}
 @PostMapping("/vendor/advertising/{id}/payment") public String submitPayment(@PathVariable String id,Principal principal,@RequestParam String utr,@RequestParam MultipartFile proof,RedirectAttributes ra){try{AdCampaign c=owned(id,principal);if(c==null)throw new IllegalArgumentException("Campaign not found.");if(!List.of("PENDING","REJECTED").contains(c.getPaymentStatus()))throw new IllegalArgumentException("Payment evidence has already been submitted or verified.");if(utr==null||!utr.trim().matches("[A-Za-z0-9]{8,30}"))throw new IllegalArgumentException("Enter a valid UTR/reference of 8–30 letters or digits.");if(campaigns.existsByPaymentUtrIgnoreCaseAndIdNot(utr.trim(),id))throw new IllegalArgumentException("This UTR/reference has already been submitted for another advertising campaign.");Map<String,Object> uploaded=uploads.uploadDocument(proof,"asmj-marketplace/advertising/payment-proofs");c.setPaymentUtr(utr.trim());c.setPaymentProofUrl((String)uploaded.get("secure_url"));c.setPaymentProofName(proof.getOriginalFilename());c.setPaymentStatus("SUBMITTED");c.setStatus("PAYMENT_SUBMITTED");c.setPaymentNote("");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyAdmins("Advertisement payment submitted",c.getVendorName()+" submitted UPI payment proof for "+c.getTitle()+".","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"VENDOR","AD_PAYMENT_SUBMITTED","AD_CAMPAIGN",id,"UPI proof submitted for verification.");ra.addFlashAttribute("successMessage","Payment proof submitted for admin verification.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/vendor/advertising";}
 @PostMapping("/vendor/advertising/{id}/creative-resubmit") public String resubmitCreative(@PathVariable String id,Principal principal,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) List<String> productIds,@RequestParam(required=false) List<String> categoryIds,@RequestParam(defaultValue="SINGLE_PRODUCT") String campaignType,@RequestParam(required=false) String destinationUrl,@RequestParam(required=false) String targetPinCodes,@RequestParam(defaultValue="CUSTOM") String bannerMode,@RequestParam(required=false) MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,RedirectAttributes ra){try{AdCampaign c=owned(id,principal);if(c==null||!"REJECTED".equals(c.getApprovalStatus())||!"VERIFIED".equals(c.getPaymentStatus()))throw new IllegalArgumentException("This campaign is not eligible for creative resubmission.");if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");String target=destinationUrl==null?"":destinationUrl.trim();String savedProductId=(productId==null||productId.isBlank())?null:productId;if(savedProductId!=null){Product product=products.findById(savedProductId).filter(x->user(principal).getId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select one of your active products."));String productTarget="/products/"+product.getId();if(target.isBlank()||target.equals(productTarget)){target=productTarget;categoryId=product.getCategoryId();}else{savedProductId=null;}}if(categoryId!=null&&!categoryId.isBlank()){String selected=categoryId;categories.findById(selected).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Use a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);if("PRODUCT_IMAGE".equalsIgnoreCase(bannerMode)){if(!"SINGLE_PRODUCT".equals(campaignType)||savedProductId==null)throw new IllegalArgumentException("Select a promoted product to use its image as the advertisement banner, or choose a separate banner.");Product bannerProduct=products.findById(savedProductId).orElseThrow(()->new IllegalArgumentException("Promoted product not found."));if(bannerProduct.getImageUrl()==null||bannerProduct.getImageUrl().isBlank())throw new IllegalArgumentException("The selected product has no image. Choose a separate advertisement banner.");c.setBannerUrl(bannerProduct.getImageUrl());c.setBannerUsesProductImage(true);}else{if(banner!=null&&!banner.isEmpty()){c.setBannerUrl((String)uploads.uploadAdvertisementBanner(banner).get("secure_url"));}else if(c.isBannerUsesProductImage()){throw new IllegalArgumentException("Upload a separate advertisement banner or choose a product image.");}c.setBannerUsesProductImage(false);}if(mobileBanner!=null&&!mobileBanner.isEmpty())c.setMobileBannerUrl((String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url"));c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());if("MULTI_PRODUCT".equals(campaignType)){List<String> valid=validateCampaignProducts(productIds,c.getVendorUserId());if(valid.size()<2)throw new IllegalArgumentException("Select at least two active products for a multi-product campaign.");savedProductId=null;categoryId=null;target="/ads/campaign/"+c.getId();c.setProductIds(valid);c.setCategoryIds(new ArrayList<>());}else if("CATEGORY".equals(campaignType)){List<String> valid=validateCampaignCategories(categoryIds);if(valid.isEmpty())throw new IllegalArgumentException("Select at least one active category.");savedProductId=null;categoryId=valid.get(0);target="/ads/campaign/"+c.getId();c.setProductIds(new ArrayList<>());c.setCategoryIds(valid);}else{c.setProductIds(new ArrayList<>());c.setCategoryIds(new ArrayList<>());}c.setCampaignType(campaignType);c.setProductId(savedProductId);c.setCategoryId(categoryId==null||categoryId.isBlank()?null:categoryId);c.setDestinationUrl(target);c.setTargetPinCodes(pins);c.setApprovalStatus("PENDING");c.setRejectionReason(null);c.setStatus("PAYMENT_VERIFIED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"VENDOR","AD_CREATIVE_RESUBMITTED","AD_CAMPAIGN",id,"Vendor resubmitted rejected creative without another payment.");ra.addFlashAttribute("successMessage","Updated creative submitted. Your verified payment remains attached to this campaign.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/vendor/advertising";}
 @GetMapping("/admin/advertising") public String admin(Principal principal,@RequestParam(required=false) String editPlacement,@RequestParam(required=false) String editPackage,Model m){service.ensureDefaults();m.addAttribute("selectedPlacement",editPlacement==null?null:placements.findById(editPlacement).orElse(null));m.addAttribute("selectedPackage",editPackage==null?null:packages.findById(editPackage).orElse(null));m.addAttribute("campaigns",campaigns.findAllByOrderByCreatedAtDesc());m.addAttribute("placements",placements.findAll());m.addAttribute("packages",packages.findAllByOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("adSettings",service.currentSettings());m.addAttribute("liveCampaigns",campaigns.findAll().stream().filter(c->c.isLive()&&placements.findByCode(c.getPlacementCode()).map(AdPlacement::isEnabled).orElse(false)).count());long impressions=campaigns.findAll().stream().mapToLong(AdCampaign::getImpressions).sum();long clicks=campaigns.findAll().stream().mapToLong(AdCampaign::getClicks).sum();m.addAttribute("totalImpressions",impressions);m.addAttribute("totalClicks",clicks);m.addAttribute("totalCtr",impressions>0?BigDecimal.valueOf(clicks*100.0/impressions).setScale(2,java.math.RoundingMode.HALF_UP):BigDecimal.ZERO);m.addAttribute("totalRevenue",campaigns.findAll().stream().filter(c->"VERIFIED".equals(c.getPaymentStatus())).map(AdCampaign::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));return "admin/advertising";}
 @GetMapping("/admin/advertising/{id}/edit") public String editCampaign(@PathVariable String id,Model m,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null){ra.addFlashAttribute("errorMessage","Advertisement campaign not found.");return "redirect:/admin/advertising";}m.addAttribute("campaign",c);m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());m.addAttribute("products",products.findByStatusOrderByCreatedAtDesc(ProductStatus.ACTIVE));return "admin/advertising-edit";}
 @PostMapping("/admin/advertising/{id}/edit") public String updateCampaign(@PathVariable String id,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) List<String> productIds,@RequestParam(required=false) List<String> categoryIds,@RequestParam(defaultValue="SINGLE_PRODUCT") String campaignType,@RequestParam(required=false) String destinationUrl,@RequestParam(required=false) String targetPinCodes,@RequestParam(defaultValue="CUSTOM") String bannerMode,@RequestParam(required=false) MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,Principal principal,RedirectAttributes ra){try{AdCampaign c=campaigns.findById(id).orElseThrow(()->new IllegalArgumentException("Advertisement campaign not found."));if("REFUNDED".equals(c.getRefundStatus())||"REFUNDED".equals(c.getPaymentStatus())||"EXPIRED".equals(c.getStatus()))throw new IllegalArgumentException("Refunded or expired campaigns cannot be edited.");if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");String target=destinationUrl==null?"":destinationUrl.trim();String savedProductId=(productId==null||productId.isBlank())?null:productId;if(savedProductId!=null){Product product=products.findById(savedProductId).filter(x->c.getVendorUserId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select an active product belonging to this campaign's vendor."));String productTarget="/products/"+product.getId();if(target.isBlank()||target.equals(productTarget)){target=productTarget;categoryId=product.getCategoryId();}else{savedProductId=null;}}if(categoryId!=null&&!categoryId.isBlank()){String selected=categoryId;categories.findById(selected).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Use a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);if("PRODUCT_IMAGE".equalsIgnoreCase(bannerMode)){if(!"SINGLE_PRODUCT".equals(campaignType)||savedProductId==null)throw new IllegalArgumentException("Select a promoted product to use its image as the advertisement banner, or choose a separate banner.");Product bannerProduct=products.findById(savedProductId).orElseThrow(()->new IllegalArgumentException("Promoted product not found."));if(bannerProduct.getImageUrl()==null||bannerProduct.getImageUrl().isBlank())throw new IllegalArgumentException("The selected product has no image. Choose a separate advertisement banner.");c.setBannerUrl(bannerProduct.getImageUrl());c.setBannerUsesProductImage(true);}else{if(banner!=null&&!banner.isEmpty()){c.setBannerUrl((String)uploads.uploadAdvertisementBanner(banner).get("secure_url"));}else if(c.isBannerUsesProductImage()){throw new IllegalArgumentException("Upload a separate advertisement banner or choose a product image.");}c.setBannerUsesProductImage(false);}if(mobileBanner!=null&&!mobileBanner.isEmpty())c.setMobileBannerUrl((String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url"));c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());if("MULTI_PRODUCT".equals(campaignType)){List<String> valid=validateCampaignProducts(productIds,c.getVendorUserId());if(valid.size()<2)throw new IllegalArgumentException("Select at least two active products for a multi-product campaign.");savedProductId=null;categoryId=null;target="/ads/campaign/"+c.getId();c.setProductIds(valid);c.setCategoryIds(new ArrayList<>());}else if("CATEGORY".equals(campaignType)){List<String> valid=validateCampaignCategories(categoryIds);if(valid.isEmpty())throw new IllegalArgumentException("Select at least one active category.");savedProductId=null;categoryId=valid.get(0);target="/ads/campaign/"+c.getId();c.setProductIds(new ArrayList<>());c.setCategoryIds(valid);}else{c.setProductIds(new ArrayList<>());c.setCategoryIds(new ArrayList<>());}c.setCampaignType(campaignType);c.setProductId(savedProductId);c.setCategoryId(categoryId==null||categoryId.isBlank()?null:categoryId);c.setDestinationUrl(target);c.setTargetPinCodes(pins);c.setApprovalStatus("PENDING");c.setApprovedBy(null);c.setApprovedAt(null);c.setRejectionReason(null);c.setStatus("VERIFIED".equals(c.getPaymentStatus())?"PAYMENT_VERIFIED":c.getStatus());c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_EDITED","AD_CAMPAIGN",id,"Campaign creative and targeting updated; approval reset for review.");ra.addFlashAttribute("successMessage","Advertisement updated. Creative approval has been reset; verify the preview and approve it again when ready.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/settings") public String saveSettings(@RequestParam String upiId,@RequestParam String payeeName,@RequestParam(required=false) String qrImageUrl,@RequestParam(required=false) MultipartFile qrImage,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){if(upiId==null||!upiId.trim().matches("[A-Za-z0-9._-]{2,256}@[A-Za-z]{2,30}")||payeeName==null||payeeName.trim().isBlank()){ra.addFlashAttribute("errorMessage","Enter a valid UPI ID and payee name.");return "redirect:/admin/advertising";}try{AdvertisingSettings s=service.currentSettings();s.setUpiId(upiId.trim());s.setPayeeName(payeeName.trim());if(qrImage!=null&&!qrImage.isEmpty())s.setQrImageUrl((String)uploads.uploadAdvertisementBanner(qrImage).get("secure_url"));else if(qrImageUrl!=null&&!qrImageUrl.isBlank()){if(!qrImageUrl.startsWith("https://"))throw new IllegalArgumentException("QR image URL must use HTTPS.");s.setQrImageUrl(qrImageUrl.trim());}s.setEnabled(enabled);s.setUpdatedAt(Instant.now());settings.save(s);audit.record(user(principal).getEmail(),"ADMIN","AD_UPI_SETTINGS_UPDATED","AD_SETTINGS","default","Advertising UPI details updated.");ra.addFlashAttribute("successMessage","Advertising UPI settings saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/placements") public String savePlacement(@RequestParam(required=false) String id,@RequestParam String code,@RequestParam String name,@RequestParam(required=false) String description,@RequestParam(required=false) String desktopSize,@RequestParam(required=false) String mobileSize,@RequestParam int maxConcurrent,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){try{if(!code.matches("[A-Z_]{3,40}")||maxConcurrent<1||maxConcurrent>20)throw new IllegalArgumentException("Placement code must use uppercase letters/underscores and capacity must be 1–20.");if(placements.findByCode(code).filter(existing->id==null||id.isBlank()||!existing.getId().equals(id)).isPresent())throw new IllegalArgumentException("That placement code is already in use.");AdPlacement p=id==null||id.isBlank()?placements.findByCode(code).orElseGet(AdPlacement::new):placements.findById(id).orElseThrow();if(p.getCode()!=null&&!p.getCode().equals(code)&&(packages.findAll().stream().anyMatch(x->x.getPlacementCode().equals(p.getCode()))||campaigns.findAll().stream().anyMatch(x->x.getPlacementCode().equals(p.getCode()))))throw new IllegalArgumentException("This placement code is already referenced by packages or campaigns. Create a new placement instead of renaming it.");p.setCode(code);p.setName(name.trim());p.setDescription(description);p.setDesktopSize(desktopSize);p.setMobileSize(mobileSize);p.setMaxConcurrent(maxConcurrent);p.setEnabled(enabled);p.setUpdatedAt(Instant.now());placements.save(p);audit.record(user(principal).getEmail(),"ADMIN","AD_PLACEMENT_SAVED","AD_PLACEMENT",p.getId(),p.getCode());ra.addFlashAttribute("successMessage","Placement saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/packages") public String savePackage(@RequestParam(required=false) String id,@RequestParam String placementCode,@RequestParam String name,@RequestParam int durationDays,@RequestParam BigDecimal price,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){try{if(placements.findByCode(placementCode).isEmpty()||durationDays<1||durationDays>365||price==null||price.signum()<0||price.compareTo(new BigDecimal("1000000"))>0)throw new IllegalArgumentException("Select a placement, duration 1–365 days and price ₹0–₹10,00,000.");if(packages.findAll().stream().anyMatch(existing->!Objects.equals(existing.getId(),id)&&existing.getPlacementCode().equals(placementCode)&&existing.getDurationDays()==durationDays))throw new IllegalArgumentException("A package with this duration already exists for the selected placement.");AdPackage p=id==null||id.isBlank()?new AdPackage():packages.findById(id).orElseThrow();p.setPlacementCode(placementCode);p.setName(name.trim());p.setDurationDays(durationDays);p.setPrice(price.setScale(2,java.math.RoundingMode.HALF_UP));p.setEnabled(enabled);p.setUpdatedAt(Instant.now());packages.save(p);audit.record(user(principal).getEmail(),"ADMIN","AD_PACKAGE_SAVED","AD_PACKAGE",p.getId(),placementCode+" / "+durationDays+" days");ra.addFlashAttribute("successMessage","Advertising package saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/payment/verify") public String verifyPayment(@PathVariable String id,Principal principal,@RequestParam(defaultValue="") String note,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"SUBMITTED".equals(c.getPaymentStatus())){ra.addFlashAttribute("errorMessage","No submitted payment is available to verify.");return "redirect:/admin/advertising";}c.setPaymentStatus("VERIFIED");c.setPaymentVerifiedBy(user(principal).getEmail());c.setPaymentVerifiedAt(Instant.now());c.setPaymentNote(note);c.setStatus("PAYMENT_VERIFIED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement payment verified","Payment for your advertisement "+c.getTitle()+" has been verified. Creative approval is still required.","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_PAYMENT_VERIFIED","AD_CAMPAIGN",id,"UPI payment verified.");ra.addFlashAttribute("successMessage","Payment verified. Creative approval is still required.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/payment/reject") public String rejectPayment(@PathVariable String id,Principal principal,@RequestParam String reason,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"SUBMITTED".equals(c.getPaymentStatus())||reason==null||reason.isBlank()){ra.addFlashAttribute("errorMessage","A submitted payment and rejection reason are required.");return "redirect:/admin/advertising";}c.setPaymentStatus("REJECTED");c.setPaymentNote(reason.trim());c.setStatus("PAYMENT_REJECTED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement payment needs correction","Payment proof for your advertisement "+c.getTitle()+" was rejected. Reason: "+reason.trim(),"AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_PAYMENT_REJECTED","AD_CAMPAIGN",id,reason);ra.addFlashAttribute("successMessage","Payment proof rejected. Vendor can resubmit.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/approve") public String approve(@PathVariable String id,Principal principal,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"VERIFIED".equals(c.getPaymentStatus())||!"PENDING".equals(c.getApprovalStatus())||"SUSPENDED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","Verify payment and ensure the creative is pending and not suspended before approval.");return "redirect:/admin/advertising";}if(c.getStartDate()==null||c.getEndDate()==null||!c.getEndDate().isAfter(c.getStartDate().minusDays(1))){ra.addFlashAttribute("errorMessage","Campaign dates are invalid.");return "redirect:/admin/advertising";}AdPlacement p=placements.findByCode(c.getPlacementCode()).orElse(null);if(p==null||!p.isEnabled()){ra.addFlashAttribute("errorMessage","The selected placement is disabled.");return "redirect:/admin/advertising";}long overlap=campaigns.findAll().stream().filter(x->!x.getId().equals(id)&&x.getPlacementCode().equals(c.getPlacementCode())&&"APPROVED".equals(x.getApprovalStatus())&&"VERIFIED".equals(x.getPaymentStatus())&&!List.of("SUSPENDED","REJECTED","EXPIRED").contains(x.getStatus())&&x.getStartDate()!=null&&x.getEndDate()!=null&&!x.getEndDate().isBefore(c.getStartDate())&&!x.getStartDate().isAfter(c.getEndDate())).count();if(overlap>=p.getMaxConcurrent()){ra.addFlashAttribute("errorMessage","This placement has reached its concurrent campaign capacity for the selected dates.");return "redirect:/admin/advertising";}c.setApprovalStatus("APPROVED");c.setApprovedBy(user(principal).getEmail());c.setApprovedAt(Instant.now());c.setStatus("APPROVED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement approved", "Your advertisement "+c.getTitle()+" has been approved and scheduled.","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_CREATIVE_APPROVED","AD_CAMPAIGN",id,"Advertisement approved and scheduled.");ra.addFlashAttribute("successMessage","Advertisement approved and scheduled.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/reject") public String reject(@PathVariable String id,Principal principal,@RequestParam String reason,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"VERIFIED".equals(c.getPaymentStatus())||!"PENDING".equals(c.getApprovalStatus())||reason==null||reason.isBlank()){ra.addFlashAttribute("errorMessage","A pending, payment-verified creative and a rejection reason are required.");return "redirect:/admin/advertising";}c.setApprovalStatus("REJECTED");c.setRejectionReason(reason.trim());c.setStatus("REJECTED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement needs correction", "Your advertisement "+c.getTitle()+" was rejected. Reason: "+reason.trim(),"AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_CREATIVE_REJECTED","AD_CAMPAIGN",id,reason);ra.addFlashAttribute("successMessage","Advertisement rejected.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/refund") public String refund(@PathVariable String id,Principal principal,@RequestParam String refundReference,@RequestParam String refundNote,@RequestParam(required=false) MultipartFile refundProof,RedirectAttributes ra){try{AdCampaign c=campaigns.findById(id).orElseThrow(()->new IllegalArgumentException("Campaign not found."));if(!"VERIFIED".equals(c.getPaymentStatus())||"REFUNDED".equals(c.getRefundStatus()))throw new IllegalArgumentException("Only a paid, not-yet-refunded campaign can be refunded.");if(refundReference==null||!refundReference.trim().matches("[A-Za-z0-9]{8,30}")||refundNote==null||refundNote.trim().isBlank())throw new IllegalArgumentException("Enter the refund UTR/reference (8–30 characters) and reason.");if(campaigns.existsByRefundReferenceIgnoreCaseAndIdNot(refundReference.trim(),id))throw new IllegalArgumentException("This refund reference has already been recorded for another campaign.");String proofUrl=null;if(refundProof!=null&&!refundProof.isEmpty())proofUrl=(String)uploads.uploadDocument(refundProof,"asmj-marketplace/advertising/refunds").get("secure_url");c.setRefundStatus("REFUNDED");c.setRefundAmount(c.getAmount());c.setRefundReference(refundReference.trim());c.setRefundProofUrl(proofUrl);c.setRefundNote(refundNote.trim());c.setRefundedBy(user(principal).getEmail());c.setRefundedAt(Instant.now());c.setPaymentStatus("REFUNDED");c.setStatus("REFUNDED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement refund recorded","A refund of ₹"+c.getRefundAmount()+" was recorded for your advertisement "+c.getTitle()+".","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_REFUNDED","AD_CAMPAIGN",id,"Full advertising campaign refund recorded by UPI.");ra.addFlashAttribute("successMessage","Full advertising refund recorded. Campaign is no longer eligible for display.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/suspend") public String suspend(@PathVariable String id,Principal principal,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null){ra.addFlashAttribute("errorMessage","Campaign not found.");return "redirect:/admin/advertising";}if("SUSPENDED".equals(c.getStatus())||"EXPIRED".equals(c.getStatus())||"REFUNDED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","This campaign cannot be suspended in its current state.");return "redirect:/admin/advertising";}c.setStatus("SUSPENDED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement suspended", "Your advertisement "+c.getTitle()+" has been suspended by ASMJ Shoppe admin.","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_SUSPENDED","AD_CAMPAIGN",id,"Campaign suspended by administrator.");ra.addFlashAttribute("successMessage","Campaign suspended. You can restore it using the Restore action if it remains eligible.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/restore") public String restore(@PathVariable String id,Principal principal,RedirectAttributes ra){try{AdCampaign c=campaigns.findById(id).orElseThrow(()->new IllegalArgumentException("Campaign not found."));if(!"SUSPENDED".equals(c.getStatus())||!"VERIFIED".equals(c.getPaymentStatus())||!"APPROVED".equals(c.getApprovalStatus())||"REFUNDED".equals(c.getRefundStatus())||c.getStartDate()==null)throw new IllegalArgumentException("Only suspended, paid and previously approved campaigns with valid dates can be restored. Edit and reapprove a changed creative first.");LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(c.getEndDate()==null||c.getEndDate().isBefore(today))throw new IllegalArgumentException("This campaign has expired and cannot be restored.");AdPlacement placement=placements.findByCode(c.getPlacementCode()).filter(AdPlacement::isEnabled).orElseThrow(()->new IllegalArgumentException("The campaign placement is disabled."));long overlap=campaigns.findAll().stream().filter(x->!x.getId().equals(id)&&x.getPlacementCode().equals(c.getPlacementCode())&&"APPROVED".equals(x.getApprovalStatus())&&"VERIFIED".equals(x.getPaymentStatus())&&!List.of("SUSPENDED","REJECTED","EXPIRED","REFUNDED").contains(x.getStatus())&&x.getStartDate()!=null&&x.getEndDate()!=null&&!x.getEndDate().isBefore(c.getStartDate())&&!x.getStartDate().isAfter(c.getEndDate())).count();if(overlap>=placement.getMaxConcurrent())throw new IllegalArgumentException("The placement has reached its capacity for these campaign dates.");c.setStatus("APPROVED");c.setUpdatedAt(Instant.now());campaigns.save(c);notifications.notifyUser(c.getVendorUserId(),"Advertisement restored", "Your advertisement "+c.getTitle()+" has been restored.","AD_CAMPAIGN",id);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_RESTORED","AD_CAMPAIGN",id,"Previously approved campaign restored.");ra.addFlashAttribute("successMessage","Campaign restored. It will display when its scheduled dates are active.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @GetMapping("/ads/target-pin") public String setTargetPin(@RequestParam(required=false) String pinCode,HttpSession session,RedirectAttributes ra){if(pinCode==null||!pinCode.matches("[0-9]{6}")){session.removeAttribute("asmjAdTargetPin");ra.addFlashAttribute("errorMessage","Enter a valid 6-digit PIN code to filter local promotions.");}else{session.setAttribute("asmjAdTargetPin",pinCode);ra.addFlashAttribute("successMessage","Promotions will be filtered for PIN code "+pinCode+".");}return "redirect:/";}
 @GetMapping(value="/ads/impression/{id}",produces="image/gif") @ResponseBody public byte[] impression(@PathVariable String id,HttpSession session){recordEvent(id,"IMPRESSION",session.getId());return java.util.Base64.getDecoder().decode("R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=");}
 @GetMapping("/ads/click/{id}") public String click(@PathVariable String id,HttpSession session,RedirectAttributes ra){
  if(id==null||id.isBlank())return "redirect:/products";
  AdCampaign c=campaigns.findById(id).filter(this::isServable).orElse(null);
  if(c==null)return "redirect:/products";
  recordEvent(id,"CLICK",session.getId());
  String type=c.getCampaignType();
  if("MULTI_PRODUCT".equals(type)||"CATEGORY".equals(type))return "redirect:/ads/campaign/"+c.getId();
  String productId=c.getProductId();
  if(productId!=null&&!productId.isBlank()){
   Product advertised=products.findById(productId).filter(p->c.getVendorUserId()!=null&&c.getVendorUserId().equals(p.getVendorUserId())&&p.getStatus()==ProductStatus.ACTIVE).orElse(null);
   if(advertised!=null)return "redirect:/products/"+advertised.getId();
  }
  // Legacy or incomplete SINGLE_PRODUCT campaigns may not have a productId.
  // Never call MongoRepository.findById with null; use only a safe internal fallback.
  String url=c.getDestinationUrl();
  if(url!=null&&!url.isBlank()&&url.matches("^/(?!/)[^\r\n]*$")&&!url.contains("..")&&!url.contains("\\"))return "redirect:"+url;
  return "redirect:/products";
 }
 @GetMapping("/ads/campaign/{id}") public String campaignLanding(@PathVariable String id,Model model){AdCampaign c=campaigns.findById(id).filter(this::isServable).orElse(null);if(c==null)return "redirect:/products";List<Product> featured;if("MULTI_PRODUCT".equals(c.getCampaignType())){featured=c.getProductIds().stream().map(pid->products.findById(pid).orElse(null)).filter(Objects::nonNull).filter(p->c.getVendorUserId().equals(p.getVendorUserId())&&p.getStatus()==ProductStatus.ACTIVE).toList();}else if("CATEGORY".equals(c.getCampaignType())){featured=products.findByCategoryIdInAndStatusOrderByCreatedAtDesc(c.getCategoryIds(),ProductStatus.ACTIVE);}else{return "redirect:/products";}model.addAttribute("campaign",c);model.addAttribute("products",featured);return "advertising/campaign-landing";}

 private void recordEvent(String id,String type,String visitor){visitor=hashVisitor(visitor);AdCampaign c=campaigns.findById(id).filter(this::isServable).orElse(null);if(c==null)return;LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(events.existsByCampaignIdAndEventTypeAndVisitorKeyAndEventDate(id,type,visitor,today))return;AdEvent e=new AdEvent();e.setCampaignId(id);e.setEventType(type);e.setVisitorKey(visitor);e.setEventDate(today);events.save(e);if("CLICK".equals(type))c.setClicks(c.getClicks()+1);else c.setImpressions(c.getImpressions()+1);campaigns.save(c);}
 private boolean isServable(AdCampaign c){return c.isLive()&&placements.findByCode(c.getPlacementCode()).map(AdPlacement::isEnabled).orElse(false);}
 private String hashVisitor(String value){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(bytes);}catch(Exception ex){return Integer.toHexString(value.hashCode());}}
 private List<String> validateCampaignProducts(List<String> ids,String vendorId){if(ids==null)return new ArrayList<>();LinkedHashSet<String> unique=new LinkedHashSet<>(ids);if(unique.size()>30)throw new IllegalArgumentException("A campaign can include up to 30 products.");for(String id:unique)products.findById(id).filter(p->vendorId.equals(p.getVendorUserId())&&p.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Every selected product must be active and belong to your vendor account."));return new ArrayList<>(unique);}
 private List<String> validateCampaignCategories(List<String> ids){if(ids==null)return new ArrayList<>();LinkedHashSet<String> unique=new LinkedHashSet<>(ids);if(unique.size()>20)throw new IllegalArgumentException("A campaign can include up to 20 categories.");for(String id:unique)categories.findById(id).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Every selected category must be active."));return new ArrayList<>(unique);}
 private List<String> parsePins(String raw){if(raw==null||raw.isBlank())return new ArrayList<>();LinkedHashSet<String> out=new LinkedHashSet<>();for(String x:raw.split("[,\\s]+")){if(!x.matches("[0-9]{6}"))throw new IllegalArgumentException("Target PIN codes must contain six digits each.");out.add(x);}if(out.size()>1000)throw new IllegalArgumentException("Maximum 1000 target PIN codes allowed.");return new ArrayList<>(out);}
 private UserAccount user(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();} private AdCampaign owned(String id,Principal p){return campaigns.findById(id).filter(c->c.getVendorUserId().equals(user(p).getId())).orElse(null);} private String message(Exception e){return e.getMessage()==null?"Unable to process advertising request.":e.getMessage();}
}
